def get_evaluation_dataset() -> dict[str, Any]:
    return {
        "jobs": [job.copy() for job in JOB_CORPUS],
        "queries": [query.copy() for query in QUERY_SET],
    }


def validate_dataset(dataset: dict[str, Any]) -> bool:
    jobs = dataset.get("jobs", [])
    queries = dataset.get("queries", [])
    if len(queries) != 30:
        return False
    valid_ids = {job["job_id"] for job in jobs}
    for query in queries:
        relevant_ids = set(query.get("relevant_job_ids", []))
        if not relevant_ids:
            return False
        if not relevant_ids.issubset(valid_ids):
            return False
        if not query.get("query") or not query.get("query_id"):
            return False
    return True
